import React, { useEffect, useMemo, useState } from "react";
import { useNavigate } from "react-router-dom";
import { createProject, createTask, getProjects, getTasksByProject, updateTask } from "../services/api";

const emptyProject = { name: "", description: "" };
const emptyTask = { title: "", description: "", assignedTo: "", dueDate: "" };

function DashboardPage() {
  const navigate = useNavigate();
  const user = JSON.parse(localStorage.getItem("user") || "{}");

  const [projects, setProjects] = useState([]);
  const [selectedProjectId, setSelectedProjectId] = useState("");
  const [tasks, setTasks] = useState([]);
  const [projectForm, setProjectForm] = useState(emptyProject);
  const [taskForm, setTaskForm] = useState(emptyTask);
  const [error, setError] = useState("");

  const selectedProject = useMemo(
    () => projects.find((project) => project._id === selectedProjectId),
    [projects, selectedProjectId]
  );

  const stats = useMemo(() => {
    const now = new Date();
    const total = tasks.length;
    const completed = tasks.filter((task) => task.status === "completed").length;
    const pending = tasks.filter((task) => task.status !== "completed").length;
    const overdue = tasks.filter(
      (task) => task.status !== "completed" && task.dueDate && new Date(task.dueDate) < now
    ).length;
    return { total, completed, pending, overdue };
  }, [tasks]);

  const loadProjects = async () => {
    const { data } = await getProjects();
    setProjects(data);
    if (!selectedProjectId && data.length > 0) setSelectedProjectId(data[0]._id);
  };

  const loadTasks = async (projectId) => {
    if (!projectId) return;
    const { data } = await getTasksByProject(projectId);
    setTasks(data);
  };

  useEffect(() => {
    loadProjects().catch(() => setError("Could not load projects"));
  }, []);

  useEffect(() => {
    loadTasks(selectedProjectId).catch(() => setError("Could not load tasks"));
  }, [selectedProjectId]);

  const logout = () => {
    localStorage.removeItem("token");
    localStorage.removeItem("user");
    navigate("/");
  };

  const onCreateProject = async (e) => {
    e.preventDefault();
    setError("");
    try {
      await createProject(projectForm);
      setProjectForm(emptyProject);
      await loadProjects();
    } catch (err) {
      setError(err.response?.data?.message || "Could not create project");
    }
  };

  const onCreateTask = async (e) => {
    e.preventDefault();
    if (!selectedProjectId) return;
    setError("");
    try {
      await createTask({ ...taskForm, projectId: selectedProjectId, assignedTo: user.id });
      setTaskForm(emptyTask);
      await loadTasks(selectedProjectId);
    } catch (err) {
      setError(err.response?.data?.message || "Could not create task");
    }
  };

  const onUpdateTaskStatus = async (taskId, status) => {
    try {
      await updateTask(taskId, { status });
      await loadTasks(selectedProjectId);
    } catch (_err) {
      setError("Could not update task");
    }
  };

  return (
    <div className="dashboard">
      <header className="topbar">
        <h1>Team Task Manager</h1>
        <div>
          <span>{user.name || "User"} ({user.role || "member"})</span>
          <button onClick={logout}>Logout</button>
        </div>
      </header>

      {error ? <p className="error">{error}</p> : null}

      <section className="stats">
        <div className="card"><h3>Total</h3><p>{stats.total}</p></div>
        <div className="card"><h3>Completed</h3><p>{stats.completed}</p></div>
        <div className="card"><h3>Pending</h3><p>{stats.pending}</p></div>
        <div className="card"><h3>Overdue</h3><p>{stats.overdue}</p></div>
      </section>

      <section className="panel-grid">
        <div className="card">
          <h2>Projects</h2>
          <select value={selectedProjectId} onChange={(e) => setSelectedProjectId(e.target.value)}>
            <option value="">Select project</option>
            {projects.map((project) => (
              <option key={project._id} value={project._id}>{project.name}</option>
            ))}
          </select>
          {user.role === "admin" ? (
            <form onSubmit={onCreateProject}>
              <input
                placeholder="Project name"
                value={projectForm.name}
                onChange={(e) => setProjectForm((prev) => ({ ...prev, name: e.target.value }))}
                required
              />
              <textarea
                placeholder="Description"
                value={projectForm.description}
                onChange={(e) => setProjectForm((prev) => ({ ...prev, description: e.target.value }))}
              />
              <button type="submit">Create Project</button>
            </form>
          ) : null}
        </div>

        <div className="card">
          <h2>Create Task</h2>
          <form onSubmit={onCreateTask}>
            <input
              placeholder="Task title"
              value={taskForm.title}
              onChange={(e) => setTaskForm((prev) => ({ ...prev, title: e.target.value }))}
              required
            />
            <textarea
              placeholder="Description"
              value={taskForm.description}
              onChange={(e) => setTaskForm((prev) => ({ ...prev, description: e.target.value }))}
            />
            <input
              type="date"
              value={taskForm.dueDate}
              onChange={(e) => setTaskForm((prev) => ({ ...prev, dueDate: e.target.value }))}
              required
            />
            <button type="submit" disabled={!selectedProject}>Add Task</button>
          </form>
        </div>
      </section>

      <section className="card">
        <h2>Tasks</h2>
        {!selectedProject ? (
          <p>Select a project to view tasks.</p>
        ) : tasks.length === 0 ? (
          <p>No tasks yet.</p>
        ) : (
          <table>
            <thead>
              <tr>
                <th>Title</th>
                <th>Status</th>
                <th>Due</th>
                <th>Assigned To</th>
              </tr>
            </thead>
            <tbody>
              {tasks.map((task) => (
                <tr key={task._id}>
                  <td>{task.title}</td>
                  <td>
                    <select value={task.status} onChange={(e) => onUpdateTaskStatus(task._id, e.target.value)}>
                      <option value="pending">Pending</option>
                      <option value="in-progress">In Progress</option>
                      <option value="completed">Completed</option>
                    </select>
                  </td>
                  <td>{new Date(task.dueDate).toLocaleDateString()}</td>
                  <td>{task.assignedTo?.name || "N/A"}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </section>
    </div>
  );
}

export default DashboardPage;
